use core::f32;

use egui::{Label, Ui, Widget};

use crate::App;

// Four lookup tables generated by build script (see "gen_name_tables()" in "build.rs")
include!(concat!(env!("OUT_DIR"), "/codegen_name.rs"));

// + 14C -> 500, 64C, 798, 8E4, A30, B7C, CC8
const NAME_ADDRESS: u32 = 0x0200_0500;
const PC_NAMES: [&str; 7] = [
  "罗宾",
  "杰拉德",
  "伊万",
  "梅雅莉",
  "加西亚",
  "加斯敏",
  "西芭",
];
// 23, 24, 3C, 3D, 3E, 40, 5B, 5C, 5D, 5E, 7B, 7C, 7D
const SPECIAL_CHARS: [char; 13] = [
  '#', '$', '<', '=', '>', '@', '[', '￥', ']', '^', '{', '|', '}',
];

impl App {
  pub fn show_name(&mut self, ui: &mut Ui) {
    Label::new(
      "该功能仅支持《黄金太阳 开启的封印》新汉化版，主要面向自定义中文名（但也支持中日英混合）。\n\
      请在输入框中输入至少一个角色的名字，再点击“运行”即可在下方的输出区域展示如何输入自定义名。\n\n\
      注：\n\
      （1）强烈推荐在“运行”后点击“Copy Output”按钮，输出内容将会复制到剪贴板，之后便可粘贴到记事本进行查看。\n\
      （2）若想命名初代主角团其他的三位成员，请在起名界面连按三下“Select”键，成功后可听到提示音。\n\
      （3）若想命名最后的三位角色，请接着上条继续输入⬆⬇⬆⬇⬅➡⬅➡⬆➡⬇⬅⬆和“Select”，成功后可听到提示音。"
    ).selectable(false).ui(ui);

    egui::Grid::new("自定义角色名")
      .num_columns(2)
      .spacing([40.0, 4.0])
      .striped(true)
      .show(ui, |ui| {
        for (i, ele) in PC_NAMES.iter().enumerate() {
          Label::new(*ele)
            .selectable(false)
            .ui(ui)
            .on_hover_text(format!("{}的自定义角色名。", ele));
          ui.add(
            egui::TextEdit::singleline(self.new_pc_names.get_mut(i).unwrap())
              .char_limit(5)
              .hint_text("请填写名字")
              .desired_width(f32::INFINITY),
          );
          ui.end_row();
        }
      });
  }

  pub fn run_name(&mut self) {
    self.out_log_c3.clear();
    for (index, pc_name_new) in self.new_pc_names.iter().enumerate() {
      if pc_name_new.is_empty() {
        continue;
      }

      let pc_name = PC_NAMES[index];
      self.out_log_c3.push_str(&format!("{pc_name}\n"));
      let char_vec: Vec<char> = pc_name_new.chars().collect();
      let mut invalid_flag = false;
      let mut name_bytes = [0; 10];
      let mut name_index = 0;

      self.out_log_c3.push_str("起名界面的输入方式：\n");
      for c in char_vec {
        if BASE_CHARACTERS_MAP.contains_key(&c) && !SPECIAL_CHARS.contains(&c) {
          let num = BASE_CHARACTERS_MAP.get(&c).unwrap();
          name_bytes[name_index] = *num;
          name_index += 1;

          self.out_log_c3.push_str(&format!("{c}：{c}\n"));
        } else if DAKUTEN_KANA_MAP.contains_key(&c) {
          let string_value = DAKUTEN_KANA_MAP.get(&c).unwrap();

          for value in string_value.chars() {
            let num = BASE_CHARACTERS_MAP.get(&value).unwrap();
            name_bytes[name_index] = *num;
            name_index += 1;
          }

          self
            .out_log_c3
            .push_str(&format!("{}：{}\n", c, DAKUTEN_KANA_MAP.get(&c).unwrap()));
        } else if COMMON_HANZI_MAP.contains_key(&c) {
          let string_value = COMMON_HANZI_MAP.get(&c).unwrap();

          for value in string_value.chars() {
            let num = BASE_CHARACTERS_MAP.get(&value).unwrap();
            name_bytes[name_index] = *num;
            name_index += 1;
          }

          self
            .out_log_c3
            .push_str(&format!("{}：{}\n", c, COMMON_HANZI_MAP.get(&c).unwrap()));
        } else if SPECIAL_HANZI_MAP.contains_key(&c) {
          let num = SPECIAL_HANZI_MAP.get(&c).unwrap();
          let num_bytes = num.to_be_bytes();
          name_bytes[name_index] = num_bytes[0];
          name_bytes[name_index + 1] = num_bytes[1];
          name_index += 2;

          self.out_log_c3.push_str(&format!(
            "{}：汉化版字库中包含该字符，但无法在游戏中正常输入，码值为{}\n",
            c,
            SPECIAL_HANZI_MAP.get(&c).unwrap()
          ));
        } else if SPECIAL_CHARS.contains(&c) {
          invalid_flag = true;
          self
            .out_log_c3
            .push_str(&format!("{c}：汉化版的控制符，不能单独使用！\n"));
        } else {
          invalid_flag = true;
          self
            .out_log_c3
            .push_str(&format!("{c}：汉化版字库中不包含该字符！\n"));
        }
      }

      if invalid_flag {
        self.out_log_c3.push_str(&format!(
          "由于存在不可用的字符，故不展示{pc_name_new}自定义名字所对应的十六进制值和金手指！\n"
        ));
      } else {
        self.out_log_c3.push_str("十六进制值：\n");
        let len = name_bytes.len();
        for (i, name_byte) in name_bytes.iter().enumerate() {
          if i + 1 == len {
            self
              .out_log_c3
              .push_str(format!("{name_byte:02X}\n").as_str());
          } else {
            self
              .out_log_c3
              .push_str(format!("{name_byte:02X} ").as_str());
          }
        }

        self.out_log_c3.push_str("金手指：\n");
        for i in 0..3 {
          if i == 2 {
            let j = i as usize;
            let address = NAME_ADDRESS + u32::try_from(index).unwrap() * 0x14C + i * 4;
            let value = u16::from_le_bytes([name_bytes[j * 4], name_bytes[j * 4 + 1]]);
            self
              .out_log_c3
              .push_str(format!("{address:08X}:{value:04X}\n").as_str());
          } else {
            let j = i as usize;
            let address = NAME_ADDRESS + u32::try_from(index).unwrap() * 0x14C + i * 4;
            let value = u32::from_le_bytes([
              name_bytes[j * 4],
              name_bytes[j * 4 + 1],
              name_bytes[j * 4 + 2],
              name_bytes[j * 4 + 3],
            ]);
            self
              .out_log_c3
              .push_str(format!("{address:08X}:{value:08X}\n").as_str());
          }
        }
      }
      self.out_log_c3.push_str("\n\n");
    }
  }
}
